mapper.select:
SELECT e.id, e.name, d.name as departmentName, ( p.gross_salary - (coalesce(pd.tax,0)+ coalesce(pd.insurance,0)+ coalesce(pd.leave_deduction,0)+ coalesce(pd.late_deduction,0)+ coalesce(pd.other_deduction,0))) AS salary,
SUM( ( p.gross_salary - (coalesce(pd.tax,0)+ coalesce(pd.insurance,0)+ coalesce(pd.leave_deduction,0)+ coalesce(pd.late_deduction,0)+ coalesce(pd.other_deduction,0))) ) OVER (PARTITION BY d.id) AS total_department_salary
FROM employee e JOIN payroll p ON p.employee_id = e.id LEFT JOIN payroll_deduction pd ON p.id = pd.payroll_id JOIN department d ON e.department_id = d.id where d.id = #{id} AND p.month = #{month}
